<script setup>import {useForm,Head} from '@inertiajs/vue3';import Errors from '../Components/Errors.vue';import {LockKeyhole} from 'lucide-vue-next';const f=useForm({email:'',password:''});</script><template><Head title="Connexion"/><section class="narrow"><div class="page-heading"><span class="eyebrow">ESPACE PROFESSIONNEL</span><h1>Agissons pour le retour de l’eau.</h1><p>Connectez-vous pour coordonner les interventions.</p></div><form class="card form-stack" @submit.prevent="f.post('/connexion',{onFinish:()=>f.reset('password')})"><LockKeyhole class="accent"/><Errors :errors="f.errors"/><label>Adresse e-mail<input v-model="f.email" type="email" autocomplete="username" required></label><label>Mot de passe<input v-model="f.password" type="password" autocomplete="current-password" required></label><button class="btn btn-primary" :disabled="f.processing">Se connecter</button><p class="muted">Les comptes professionnels sont créés par la coordination.</p></form></section></template>
